import{_ as e,o as s,c as i,a3 as a}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation","description":"","frontmatter":{"translationSource":{"title":"迟滞输出现象(4n物品卡半格)整理与原理探究","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=tZlUFONP0H56rrjqpWpAn9","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/output-lag-observations-and-mechanism-investigation"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/output-lag-observations-and-mechanism-investigation"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/output-lag-observations-and-mechanism-investigation"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/output-lag-observations-and-mechanism-investigation"}]]},"headers":[],"relativePath":"output-lag-observations-and-mechanism-investigation.md","filePath":"logistics/src/page-tZlUFONP0H56rrjqpWpAn9.md"}'),n={name:"output-lag-observations-and-mechanism-investigation.md"};function o(r,t,d,l,c,m){return s(),i("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="迟滞输出现象-4n物品卡半格-整理与原理探究" aria-hidden="true"></span><span class="logistics-source-anchor" id="output-lag-4n-items-stall-for-half-a-tile-observations-and-mechanism-investigation" aria-hidden="true"></span><h1 id="output-lag-4n-items-stall-at-half-tile-positions-observations-and-mechanism-investigation" tabindex="-1">Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation <a class="header-anchor" href="#output-lag-4n-items-stall-at-half-tile-positions-observations-and-mechanism-investigation" aria-label="Permalink to &quot;Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation&quot;">​</a></h1><blockquote><p>Source page ID: <code>tZlUFONP0H56rrjqpWpAn9</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=tZlUFONP0H56rrjqpWpAn9" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><table tabindex="0"><thead><tr><th>Title</th><th>Details</th><th>Single choice</th><th>Date</th><th>Image</th></tr></thead><tbody><tr><td>Phenomenon discovered</td><td>@晨隐_ formally raised this problem while experimenting with subtraction</td><td>Related experiments</td><td></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-8395db0bd51e3909.q90-4afcb829f8cf2c22.webp" alt="C$XI5D1D68S@~ZS1CBDpng"></td></tr><tr><td>Hypotheses about trigger conditions</td><td></td><td>Related hypotheses</td><td></td><td></td></tr><tr><td>First reproducible experiment</td><td>@天云-翱翔天际 found a reproducible trigger for this phenomenon. It requires a full Protocol Stash, with the belt ultimately leading from the Splitter through a logistics component to the factory placed later than the belt leading to the full stash. The ratio is positively correlated with the distance from the Splitter to the logistics component; when several Splitters are present, it is not yet clear which distance applies.</td><td>Related experiments</td><td></td><td></td></tr><tr><td>Hypotheses about the triggering mechanism</td><td></td><td>Related hypotheses</td><td></td><td></td></tr><tr><td>A new batch of experimental results—1</td><td>@jnk1698 completed new mysterious experiments; see the expandable sections below</td><td>Related experiments</td><td></td><td></td></tr><tr><td>A similar problem with water pipes</td><td>@jnk1698 investigated an anomaly that also occurs when water pipes are arranged in a similar structure</td><td>Related experiments</td><td></td><td></td></tr></tbody></table><details><summary>Experiment 1</summary><blockquote><p>Place the belt connecting to the right Stash&#39;s input last.</p><p>The upper route&#39;s logistics-component + belt can be changed to belt + logistics-component or logistics-component + logistics-component, but not a single belt section or single logistics component, nor belt + logistics-component + belt, nor logistics-component + belt + logistics-component, ?</p><p>The Stash on the right is optional too.</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-49770de69f8fa907.q90-e3406bb657beadd3.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-b9152f887663e1b0.q90-9c77e869e76bf7b3.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-221f41b3bdd2a879.q90-a111f3b94b6963dd.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9f6f27ee0a08498a.q90-69e39f6f36eb4b7b.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-814c2784e0c65ed2.q90-c77e8aa17ec93195.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-084772e32fbb42b7.q90-df98765d05c3d7ab.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-c4d320d51e7df9d4.q90-10f3d3451db10cd4.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-c71f8dd9385511a4.q90-fc174ec704bb600f.webp" alt="Image"></td></tr></tbody></table></details><details><summary>Water-pipe experiment</summary><p>Use this structure to observe the result:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-40c0238d9a7acd64.q90-6639e3e07f4dc54a.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p><p>First circulate water, then connect higher-priority Jincao Solution, routing it through the structure that causes output lag.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-16d181bcdeb5cae3.q90-bc2f17055347637f.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-64d9129f1bceaf9f.q90-3ef6dcc129bff8cd.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p><p>Fluids behave slightly differently from belts: 2n units stall for 1 tile, where n is the distance from the splitter to the next logistics component; values below 1 count as 1.</p></details><details><summary>Low-priority insertion into the “4n, 1s stall” item sequence</summary><p>Use experiment 1&#39;s output sequence for a priority merge with another, lower-priority item stream. One item from the other branch merges after n+1 items in the sequence. Here n no longer treats 0 as 1.</p></details><details><summary>Experiment 2</summary><p>While @恒星泰斗 and @c tested the forward-loop structure (see the bugs section of damping theory), a possible “4n, 1s stall” appeared: round-robin output among forward-loop structure 1, straight belt 2 and straight belt 3 followed a 1312 cycle. @恒星泰斗 later confirmed the trigger, shown below: place the converger last.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a7843e55dbc29283.q90-e4f816051f1caa48.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p><p>@jnk considers the control port irrelevant, giving:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fd40383fcc005226.q90-2d2c8212152ecc30.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p></details><details><summary>Floating-point position hypotheses and experiments</summary><p>@Fatal Error A1012 conducted the experiment below. Might the converger at the Stash output cause a “4n, 2s stall” here?</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1d008357d9f1f9d5.q90-628c17a431b90ceb.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cfb588dede9a5847.q90-35a2aa61b25841b1.webp" alt="Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation"></p><p>The second image clearly does not have one-tile item spacing. Investigation and reproduction attempts suggest that after collecting one item from the belt, other items render at their actual positions. Related test images follow:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-8e7d3ac3b6e624d0.q90-e0752050a2c7bffb.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-0d861dc6f16ec3bd.q90-e27c11f007e73e0b.webp" alt="Image"></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-de72f92436ef814a.q90-326aaf06452867a4.webp" alt="Image"></td><td></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-81d56e5da746fe42.q90-0721dcd78d7d6d36.webp" alt="Image"></td><td></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-06fe53272bf33b19.q90-ed04a4b7c8af3dd1.webp" alt="Image"></td><td></td></tr><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-484b29cc5598323a.q90-967996c2261cc2f9.webp" alt="Image"></td><td></td></tr></tbody></table></details><p>Current experiments suggest item positions are fractional rather than limited to two states. Collecting an item from a belt reveals the true distribution, which realigns to two states after passing a logistics component. The trigger is still unknown; this may cause some round-robin phenomena.</p><details><summary>Chat log: current research summary</summary><p>jnk 2026/5/23 14:54:02</p><p>jnk</p><p>Can we currently divide the “4n, 1s stall” into two categories? No other triggers have been found, or confirmed to cause this same issue.</p><p>One is caused by a forward loop with a converger flush against a Stash output.</p><p>The other occurs when one side of a splitter cannot output. This second category divides into an open-ended side unable to output and a non-open-ended side unable to output.</p><p>Among current triggers, the converger forward-loop category only shows “4 items, 1s stall.” The splitter category depends on the length of the logistics component attached to the final route&#39;s splitter, and that component must be followed by another logistics component. The open-ended splitter-side category requires exactly 2 logistics components in the open-ended direction, and one qualifying side suffices. As for the non-open-ended splitter-side category; for splitter cases, we do not currently know whether blocking is necessary.</p><p>All of this is empirical and may change with experimental results.</p></details><p>@c extended experiment one: if the downstream route has multiple outputs, all must be disconnected and placed again.</p><details><summary>Chat log: induce–transfer–move logic</summary><p>jnk 2026/8/13 8:13:36</p><p>Induce–transfer–move logic:<br> An item moves/transfers only once.<br> When a logistics component updates, it first induces movement of items inside the downstream component, checks whether its own items at its endpoint can transfer into the next component, then moves its own internal items.<br> During a splitter&#39;s induction phase, if the induced component is a converger, the converger may transfer an item; this depends on the order of connecting the converger to its downstream component and to the upstream splitter.</p><p>Assume the upstream of two components updates first:<br> x;x,x#x means no item; 7～0 means a newly entered item through to one about to exit; upstream is on the left<br> 7;x,x...#... skips readily understandable time<br> 1;x,x<br> :0;x,x#move; : indicates actions within the same tick<br> :0;x,x#induce<br> :0;x,x#transfer, but the item just moved and cannot transfer<br> 0:x,x<br> 7;7,x...<br> 0;0,x<br> :0;x,7#induce<br> :x;7,7#transfer<br> :x;7,7<br> :x;7,7#downstream induce–transfer–move changes nothing; both items have already moved/transferred<br> 7;7,7...#one item transferred since 0;0,x<br> 0;0,0<br> :0;0,0...#move; skip the upstream induce–transfer–move and downstream induce, all unchanged<br> :0;0,x#downstream transfer<br> :0;x,7#downstream move<br> 0;x,7#a 1-tick stall occurs<br> :0;x,6<br> :x;7,6<br> :x;7,6<br> 7;7,6...#two items transferred since 0;0,x<br> 1;1,0<br> :1;0,0#induce<br> :1;0,0#transfer<br> :0;0,0#move<br> :0;0,0#downstream induce<br> :0;0,x#downstream transfer<br> :0;0,x#downstream move<br> 0;0,x#since the previous 0;0,x, two items transferred and one stall occurred: a 4*2, 1s stall (4tick=1s). It is easy to see that downstream-component length determines n in the “4n, 1s stall.”</p></details><p>Further study of forward loops requires investigating a loop without downstream output, as shown:</p><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f9ad0ee9a15d21c5.q90-9c61717ccb8fe1e6.webp" alt="Image"></td></tr></tbody></table></div>',1)])])}const h=e(n,[["render",o]]);export{g as __pageData,h as default};
